import unittest, json, pathlib
P=pathlib.Path(__file__).parent

class ExpandedRicoGraphTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        g=json.loads((P/'graph.json').read_text())
        cls.n={x['id']:x for x in g['nodes']};cls.e=g['edges'];cls.s=g['sources'];cls.summary=g['summary']
    def find(self,src,target,relation=None):
        return [e for e in self.e if e['source']==src and e['target']==target and (relation is None or e['relation']==relation)]
    def test_fairwind_displayed_partners_are_sourced(self):
        expected={'accenture','armadin','cis','crowdstrike','datadog','deloitte','mckinsey','menlo','paloalto','robinhood','snowflake','wiz'}
        actual={e['source'] for e in self.e if e['target']=='fairwind' and e['relation']=='featured_fairwind_partner' and e['evidence_state']=='documented' and e['evidence_id']=='FAIRWIND_PARTNERS'}
        self.assertEqual(actual,expected)
    def test_named_three_program_overlap_exact(self):
        cohorts=[{e['source'] for e in self.e if e['target']==program and e['relation']==relation and e['evidence_state']=='documented'} for program,relation in [('glasswing','named_launch_partner'),('daybreak','named_daybreak_partner'),('fairwind','featured_fairwind_partner')]]
        self.assertEqual(set.intersection(*cohorts),{'crowdstrike','paloalto'})
        self.assertNotIn('cisco',cohorts[2])
    def test_removing_fairwind_source_eliminates_triple_overlap(self):
        es=[e for e in self.e if e['evidence_id']!='FAIRWIND_PARTNERS']
        cohorts=[{e['source'] for e in es if e['target']==program and e['relation']==relation} for program,relation in [('glasswing','named_launch_partner'),('daybreak','named_daybreak_partner'),('fairwind','featured_fairwind_partner')]]
        self.assertEqual(set.intersection(*cohorts),set())
    def test_musk_and_spacex_corporate_separation(self):
        self.assertIn('musk',self.n);self.assertIn('spacex',self.n);self.assertIn('xai',self.n)
        self.assertEqual(self.n['spacexai']['label'],'SpaceX.AI LLC')
        self.assertTrue(self.find('spacex','xai','acquired_wholly_owned_subsidiary'))
        self.assertTrue(self.find('spacex','spacexai','wholly_owned_subsidiary'))
        self.assertTrue(self.find('musk','spacex','CEO'))
    def test_google_spacex_contract_and_beneficial_ownership_are_distinct(self):
        es=self.find('google','spacex')
        own=[x for x in es if x['relation']=='SpaceX_Class_A_beneficial_ownership_reported']
        fees=[x for x in es if x['relation']=='SpaceX_compute_customer_monthly_contract_fee']
        self.assertEqual(len(own),1);self.assertEqual(len(fees),1)
        self.assertEqual((own[0]['amount'],own[0]['unit']),(7.2,'% of SpaceX Class A shares, not total votes'))
        self.assertEqual((fees[0]['amount'],fees[0]['unit']),(920,'USD millions/month contracted from October 2026, not evidence of payments'))
        self.assertNotEqual(own[0]['evidence_id'],fees[0]['evidence_id'])
    def test_thiel_5_5_percent_not_independent_double_count(self):
        es=self.find('thiel','spacex','aggregate_beneficial_ownership_Thiel_and_reporting_entities')
        self.assertEqual(len(es),1)
        self.assertEqual(es[0]['amount'],5.5)
        self.assertIn('not total votes',es[0]['unit'])
    def test_wiz_acquired_not_just_announced(self):
        es=self.find('google','wiz','completed_acquisition')
        self.assertEqual(len(es),1);self.assertEqual(es[0]['amount'],29.5)
        self.assertEqual(es[0]['valid_from'],'2026-03-11')
    def test_palantir_ai_model_integration_is_not_enterprise_control(self):
        providers={'openai','anthropic','google','xai'}
        actual={e['target'] for e in self.e if e['source']=='palantir' and e['relation']=='aip_supports_models_from_provider'}
        self.assertEqual(actual,providers)
        for e in self.e:
            if e['source']=='palantir' and e['target'] in providers:
                self.assertNotIn(e['relation'],{'controls','owns','directs'})
    def test_iqt_paths_not_artificial_direct_investments(self):
        self.assertTrue(self.find('iqt','keyhole','historical_strategic_investment'))
        self.assertTrue(self.find('google','keyhole','acquired_company'))
        self.assertTrue(self.find('iqt','palantir','historical_early_investor'))
        for provider in ['openai','anthropic','xai','google']:
            self.assertFalse([e for e in self.find('iqt',provider) if 'invest' in e['relation'].lower()])
    def test_alliance_connects_spacexai_palantir_cyberfirms(self):
        for nid in ['palantir','spacexai','cisco','crowdstrike','paloalto','nvidia','wiz']:
            self.assertTrue(self.find(nid,'secure_alliance','named_inaugural_partner'))
    def test_graph_version_and_source_registry(self):
        self.assertEqual(self.summary['direct_three_program_featured_overlap'],['CrowdStrike','Palo Alto Networks'])
        for e in self.e:
            self.assertIn(e['evidence_id'],self.s)
            if e['evidence_state']=='documented':
                self.assertNotIn(self.s[e['evidence_id']]['kind'],{'user_report','investigator_supplied_synthesis'})

if __name__=='__main__': unittest.main(verbosity=2)
